package com.example.complaintmanagement.service.impl; import com.example.complaintmanagement.dto.CategoryDtos.*; import com.example.complaintmanagement.entity.Category; import com.example.complaintmanagement.exception.*; import com.example.complaintmanagement.mapper.CategoryMapper; import com.example.complaintmanagement.repository.CategoryRepository; import com.example.complaintmanagement.service.CategoryService; import org.springframework.stereotype.Service; import java.util.*; @Service public class CategoryServiceImpl implements CategoryService {final CategoryRepository r;final CategoryMapper m=new CategoryMapper(); public CategoryServiceImpl(CategoryRepository r){this.r=r;} public List<Response> all(){return r.findAll().stream().map(m::toResponse).toList();} public Response get(Long id){return m.toResponse(r.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found with id: "+id)));} public Response create(Request x){if(r.existsByNameIgnoreCase(x.name()))throw new BadRequestException("Category already exists");return m.toResponse(r.save(Category.builder().name(x.name()).description(x.description()).active(x.active()).build()));} public Response update(Long id,Request x){Category c=r.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found with id: "+id));if(!c.getName().equalsIgnoreCase(x.name())&&r.existsByNameIgnoreCase(x.name()))throw new BadRequestException("Category already exists");c.setName(x.name());c.setDescription(x.description());c.setActive(x.active());return m.toResponse(r.save(c));} public void delete(Long id){if(!r.existsById(id))throw new ResourceNotFoundException("Category not found with id: "+id);r.deleteById(id);} }
